public final class ZeroReportTest{public static void main(String[] a){String[] results={"READ_MAP\n0\n4096\n16384\n2048\n1\n2048 + 2048\n","WIMTREE_LIST\nF owned.txt • 5 B","WIMTREE_ALL_OK 2\n4096\n1","UL_LIST\nOwned Demo • SLUS_123.45 • DVD • 1","UL_CREATED\nSLUS_123.45\n1\nabc","ZERO_VERIFIED 32768 0","CHD_RAW_OK 2048\nSHA-256: abc","ARCHIVE_ALL_OK 2\n4096\n0","FSIMAGE_ALL_OK 2\n4096\n1","ARCHIVE_LIST\nF owned.txt • 5 B\nARCHIVE_MORE 3","FSIMAGE_LIST\nS shortcut • 0 B"};int count=0;for(String r:results){String en=ReportText.render(r,false),ar=ReportText.render(r,true);if(en.matches("(?s).*[\\u0600-\\u06ff].*"))throw new AssertionError(en);if(!ar.matches("(?s).*[\\u0600-\\u06ff].*"))throw new AssertionError(ar);count+=2;}if(!ReportText.render(results[5],false).contains("1970-01-01T00:00:00Z"))throw new AssertionError("UTC");if(!ReportText.render(results[8],false).contains("omitted: 1"))throw new AssertionError("omitted paths");System.out.println("PASS: "+(count+2)+" English/Arabic-only archive/FSimage/CHD/zero-record/UTC result checks");}}
